87	func TestEqSemantics(t *testing.T) {
88		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
89			{"id":"r1","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"Pro"}]}]}]}`
90		cases := map[string]string{
91			`{"plan":"Pro"}`:  "match",
92			`{"plan":"pro"}`:  "case",       // 区分大小写
93			`{"plan":" Pro"}`: "whitespace", // 不裁剪空白
94			`{}`:              "missing",
95		}
96		for ctxRaw, label := range cases {
97			got := eval(t, cfg, "f", ctxRaw)
98			matched := got.Reason == EvalRule
